using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;
// Review-only snapshots, called at explicit capture fences; never attached to production.
public static class CurrentGreetingState {
 [Serializable]sealed class State{public string utc,stage,sourceIdentitySHA;public double uptime;public int frame,draws;public bool splashFinished,sRGBWrite,postEnabled;public RT active,cameraActive,target;public Actor[] actors;}
 [Serializable]sealed class RT{public bool exists,sRGB;public string name,format;public int width,height,msaa;}
 static RT Target(RenderTexture t){return t?new RT{exists=true,name=t.name,format=t.graphicsFormat.ToString(),width=t.width,height=t.height,msaa=t.antiAliasing,sRGB=t.sRGB}:new RT();}
 [Serializable]sealed class Actor{public string mesh;public int vertices;public Matrix4x4 rendererWorld,rendererInverse,rendererNormal,rootWorld,rootNormal;public Matrix4x4[] bindposes,boneWorld,boneLocal,boneNormal;public float[] blendWeights;public Bounds localBounds;public bool visible,enabled,updateWhenOffscreen,forceMatrix;public string quality;public MaterialState[] materials;}
 [Serializable]sealed class MaterialState{public string name,shader;public string[] keywords;public int renderQueue,passes;public bool instancing,rendererBlockEmpty,indexBlockEmpty;public Property[] properties;}
 [Serializable]sealed class Property{public string name,type;public int integer,rendererInteger,indexInteger;public float scalar,rendererScalar,indexScalar;public Color color,rendererColor,indexColor;public Vector4 vector,rendererVector,indexVector;public bool rendererOverride,indexOverride;public TextureState texture,rendererTexture,indexTexture;public Vector2 scale,offset;}
 [Serializable]sealed class TextureState{public string name,type,graphicsFormat;public int instanceID,width,height,mips,aniso,loaded,loading,desired,requested,priority;public float bias;public string filter,wrapU,wrapV,wrapW;public bool isTexture2D,streaming,requestedLoaded;}
 static TextureState Tex(Texture t){if(!t)return null;var x=new TextureState{name=t.name,type=t.GetType().FullName,instanceID=t.GetInstanceID(),width=t.width,height=t.height,mips=t.mipmapCount,graphicsFormat=t.graphicsFormat.ToString(),aniso=t.anisoLevel,bias=t.mipMapBias,filter=t.filterMode.ToString(),wrapU=t.wrapModeU.ToString(),wrapV=t.wrapModeV.ToString(),wrapW=t.wrapModeW.ToString()};var d=t as Texture2D;if(d){x.isTexture2D=true;x.streaming=d.streamingMipmaps;x.priority=d.streamingMipmapsPriority;x.loaded=d.loadedMipmapLevel;x.loading=d.loadingMipmapLevel;x.desired=d.desiredMipmapLevel;x.requested=d.requestedMipmapLevel;x.requestedLoaded=d.IsRequestedMipmapLevelLoaded();}return x;}
 public static void Write(GameObject[] actors,string path,string stage,CurrentSkinningRenderCounter counter,string sourceIdentitySHA){
  var states=new List<Actor>();foreach(var actor in actors){var s=actor.GetComponentInChildren<SkinnedMeshRenderer>();var mesh=s.sharedMesh;var bw=new Matrix4x4[s.bones.Length];var bl=new Matrix4x4[bw.Length];var bn=new Matrix4x4[bw.Length];for(int i=0;i<bw.Length;i++){bw[i]=s.bones[i].localToWorldMatrix;bl[i]=Matrix4x4.TRS(s.bones[i].localPosition,s.bones[i].localRotation,s.bones[i].localScale);bn[i]=bw[i].inverse.transpose;}var weights=new float[mesh.blendShapeCount];for(int i=0;i<weights.Length;i++)weights[i]=s.GetBlendShapeWeight(i);
   var rendererBlock=new MaterialPropertyBlock();s.GetPropertyBlock(rendererBlock);var mats=new List<MaterialState>();for(int index=0;index<s.sharedMaterials.Length;index++){var m=s.sharedMaterials[index];if(!m)throw new Exception("Null material in Greeting witness");var block=new MaterialPropertyBlock();s.GetPropertyBlock(block,index);var ps=new List<Property>();for(int i=0;i<m.shader.GetPropertyCount();i++){string name=m.shader.GetPropertyName(i);int id=Shader.PropertyToID(name);var type=m.shader.GetPropertyType(i);var p=new Property{name=name,type=type.ToString(),rendererOverride=rendererBlock.HasProperty(id),indexOverride=block.HasProperty(id)};
    if(type==ShaderPropertyType.Int){p.integer=m.GetInteger(id);p.rendererInteger=rendererBlock.GetInteger(id);p.indexInteger=block.GetInteger(id);}else if(type==ShaderPropertyType.Float||type==ShaderPropertyType.Range){p.scalar=m.GetFloat(id);p.rendererScalar=rendererBlock.GetFloat(id);p.indexScalar=block.GetFloat(id);}else if(type==ShaderPropertyType.Color){p.color=m.GetColor(id);p.rendererColor=rendererBlock.GetColor(id);p.indexColor=block.GetColor(id);}else if(type==ShaderPropertyType.Vector){p.vector=m.GetVector(id);p.rendererVector=rendererBlock.GetVector(id);p.indexVector=block.GetVector(id);}else if(type==ShaderPropertyType.Texture){p.texture=Tex(m.GetTexture(id));p.rendererTexture=Tex(rendererBlock.GetTexture(id));p.indexTexture=Tex(block.GetTexture(id));p.scale=m.GetTextureScale(name);p.offset=m.GetTextureOffset(name);int st=Shader.PropertyToID(name+"_ST");p.rendererVector=rendererBlock.GetVector(st);p.indexVector=block.GetVector(st);}ps.Add(p);
   }mats.Add(new MaterialState{name=m.name,shader=m.shader.name,keywords=m.shaderKeywords,renderQueue=m.renderQueue,passes=m.passCount,instancing=m.enableInstancing,rendererBlockEmpty=rendererBlock.isEmpty,indexBlockEmpty=block.isEmpty,properties=ps.ToArray()});}
   states.Add(new Actor{mesh=mesh.name,vertices=mesh.vertexCount,rendererWorld=s.localToWorldMatrix,rendererInverse=s.worldToLocalMatrix,rendererNormal=s.worldToLocalMatrix.transpose,rootNormal=s.rootBone?s.rootBone.worldToLocalMatrix.transpose:Matrix4x4.identity,rootWorld=s.rootBone?s.rootBone.localToWorldMatrix:Matrix4x4.identity,bindposes=mesh.bindposes,boneWorld=bw,boneLocal=bl,boneNormal=bn,blendWeights=weights,localBounds=s.localBounds,visible=s.isVisible,enabled=s.enabled,updateWhenOffscreen=s.updateWhenOffscreen,forceMatrix=s.forceMatrixRecalculationPerRender,quality=s.quality.ToString(),materials=mats.ToArray()});
  }
  var camera=UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsSortMode.None);if(camera.Length!=1)throw new Exception("Greeting camera count changed");var post=camera[0].GetComponent<LighFight.Runtime.FittedFilmicCamera>();
  File.WriteAllText(path,JsonUtility.ToJson(new State{sRGBWrite=GL.sRGBWrite,active=Target(RenderTexture.active),cameraActive=Target(camera[0].activeTexture),target=Target(camera[0].targetTexture),postEnabled=post&&post.enabled,utc=DateTime.UtcNow.ToString("O"),stage=stage,sourceIdentitySHA=sourceIdentitySHA,uptime=Time.realtimeSinceStartupAsDouble,frame=Time.frameCount,draws=counter.renders,splashFinished=SplashScreen.isFinished,actors=states.ToArray()},true));
  for(int i=0;i<actors.Length;i++)CurrentBufferStateSnapshot.Write(actors[i].GetComponentInChildren<SkinnedMeshRenderer>(),path+"-camera-light-post-a"+i+".json");
 }
}
